 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The 2-colored line is a boundary; recolor the background strip immediately
    # beyond it, opposite the side containing the non-background object, to 8.
    h, w = len(grid), len(grid[0])
    if all(all(v == 2 for v in row) for row in grid):
        boundary = next(r for r, row in enumerate(grid) if 2 in row)
        # Horizontal boundary: object's side is detected from non-2/non-background pixels.
        object_rows = [r for r, row in enumerate(grid) if any(v not in (2, 3) for v in row)]
        if object_rows and object_rows[0] > boundary:
            out[boundary - 1] = [8] * w
        elif object_rows and object_rows[0] < boundary:
            out[boundary + 1] = [8] * w
    else:
        marker = next(c for c in range(w) if any(row[c] == 2 for row in grid))
        object_cells = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (2,5)]
        if object_cells:
            # Color the full adjacent column on the side opposite the object.
            obj_col = sum(c for r,c in object_cells) / len(object_cells)
            fill_col = marker - 1 if obj_col > marker else marker + 1
            if 0 <= fill_col < w:
                for r in range(h):
                    out[r][fill_col] = 8
    return out
